/**
 * Error Pattern Constraint Store — SQLite-backed persistence for error-pattern constraints.
 * Stores constraints generated by error-pattern-detector.js with configurable TTL,
 * operator override tracking (dismiss/extend/escalate), and auto-expiry support.
 */

import Database from '../persistence/sqlite-provider.js';
import { randomUUID } from 'crypto';
import { createLogger } from '../logger.js';
import { mkdirSync, existsSync } from 'fs';
import { dirname } from 'path';
import { validateTimelineEvent, EVENT_TYPES } from './timeline-schema.js';

const log = createLogger('error-pattern-constraint-store');

export class ErrorPatternConstraintStore {
  /**
   * @param {Object} options - Store configuration
   * @param {string} options.dbPath - Path to SQLite database file
   * @param {number} [options.defaultTtlMs=7200000] - Default TTL in ms (default: 2 hours)
   */
  constructor(options = {}) {
    if (!options.dbPath) {
      throw new TypeError('dbPath option is required');
    }

    this.dbPath = options.dbPath;
    this.defaultTtlMs = options.defaultTtlMs || 7200000; // 2 hours default

    // Ensure parent directory exists
    const dir = dirname(this.dbPath);
    try {
      mkdirSync(dir, { recursive: true });
    } catch (err) {
      if (err.code !== 'EEXIST') {
        throw err;
      }
    }

    // Open/create SQLite database
    this.db = new Database(this.dbPath);

    // Enable WAL mode for better concurrency
    this.db.pragma('journal_mode = WAL');

    // Create error_pattern_constraints table
    this.db.exec(`
      CREATE TABLE IF NOT EXISTS error_pattern_constraints (
        id TEXT PRIMARY KEY,
        agentId TEXT NOT NULL,
        errorCategory TEXT,
        penaltyFactor REAL NOT NULL DEFAULT 0.2,
        patternId TEXT NOT NULL,
        triggeringFailures TEXT NOT NULL,
        createdAt TEXT NOT NULL,
        expiresAt TEXT NOT NULL,
        dismissedAt TEXT,
        dismissedBy TEXT,
        escalated BOOLEAN NOT NULL DEFAULT 0,
        extendedCount INTEGER NOT NULL DEFAULT 0,
        lastExtendedAt TEXT
      )
    `);

    // Create indexes for efficient queries
    this.db.exec(`
      CREATE INDEX IF NOT EXISTS idx_constraints_agentId ON error_pattern_constraints(agentId);
      CREATE INDEX IF NOT EXISTS idx_constraints_errorCategory ON error_pattern_constraints(errorCategory);
      CREATE INDEX IF NOT EXISTS idx_constraints_patternId ON error_pattern_constraints(patternId);
      CREATE INDEX IF NOT EXISTS idx_constraints_expiresAt ON error_pattern_constraints(expiresAt);
      CREATE INDEX IF NOT EXISTS idx_constraints_agentId_expiresAt ON error_pattern_constraints(agentId, expiresAt);
      CREATE INDEX IF NOT EXISTS idx_constraints_dismissedAt ON error_pattern_constraints(dismissedAt);
    `);

    // Prepare statements for reuse
    this._insertStmt = this.db.prepare(`
      INSERT INTO error_pattern_constraints 
      (id, agentId, errorCategory, penaltyFactor, patternId, triggeringFailures, createdAt, expiresAt, dismissedAt, dismissedBy, escalated, extendedCount, lastExtendedAt)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `);

    this._getStmt = this.db.prepare(`
      SELECT id, agentId, errorCategory, penaltyFactor, patternId, triggeringFailures, 
             createdAt, expiresAt, dismissedAt, dismissedBy, escalated, extendedCount, lastExtendedAt
      FROM error_pattern_constraints
      WHERE id = ?
    `);

    this._listActiveStmt = this.db.prepare(`
      SELECT id, agentId, errorCategory, penaltyFactor, patternId, triggeringFailures,
             createdAt, expiresAt, dismissedAt, dismissedBy, escalated, extendedCount, lastExtendedAt
      FROM error_pattern_constraints
      WHERE dismissedAt IS NULL 
        AND (expiresAt IS NULL OR expiresAt > ?)
      ORDER BY createdAt DESC
    `);

    this._removeStmt = this.db.prepare(`
      UPDATE error_pattern_constraints
      SET dismissedAt = ?, dismissedBy = ?
      WHERE id = ?
    `);

    this._updateTTLStmt = this.db.prepare(`
      UPDATE error_pattern_constraints
      SET expiresAt = ?, extendedCount = extendedCount + 1, lastExtendedAt = ?
      WHERE id = ?
    `);

    this._escalateStmt = this.db.prepare(`
      UPDATE error_pattern_constraints
      SET escalated = 1
      WHERE id = ?
    `);

    this._pruneExpiredStmt = this.db.prepare(`
      SELECT id
      FROM error_pattern_constraints
      WHERE dismissedAt IS NULL 
        AND expiresAt IS NOT NULL 
        AND expiresAt <= ?
    `);

    this._deleteExpiredStmt = this.db.prepare(`
      DELETE FROM error_pattern_constraints
      WHERE id = ?
    `);
  }

  /**
   * Add a new constraint.
   * @param {Object} constraint - Constraint data
   * @param {string} constraint.agentId - Agent identifier
   * @param {string} [constraint.errorCategory] - Error category
   * @param {number} [constraint.penaltyFactor] - Penalty factor (default: 0.2)
   * @param {string} constraint.patternId - Pattern identifier
   * @param {Array} constraint.triggeringFailures - Array of triggering failure IDs
   * @param {string|number} [constraint.expiresAt] - Expiration timestamp (ISO string or ms)
   * @param {string} [constraint.id] - Optional constraint ID (auto-generated if missing)
   * @param {string} [constraint.dismissedBy] - Optional operator ID who created it
   * @returns {string} The ID of the created constraint
   */
  add(constraint) {
    const {
      agentId,
      errorCategory,
      penaltyFactor = 0.2,
      patternId,
      triggeringFailures,
      expiresAt,
      id,
      dismissedBy,
    } = constraint;

    if (!agentId || !patternId || !triggeringFailures) {
      throw new TypeError('Missing required fields: agentId, patternId, triggeringFailures');
    }

    const now = new Date().toISOString();
    const constraintId = id || `constraint-${Date.now()}-${Math.random().toString(36).substring(2, 9)}`;
    
    // Calculate expiresAt if not provided
    let expiresAtValue = expiresAt;
    if (!expiresAt) {
      const expiryTime = Date.now() + this.defaultTtlMs;
      expiresAtValue = new Date(expiryTime).toISOString();
    } else if (typeof expiresAt === 'number') {
      expiresAtValue = new Date(expiresAt).toISOString();
    } else {
      expiresAtValue = expiresAt;
    }

    try {
      this._insertStmt.run(
        constraintId,
        agentId,
        errorCategory || null,
        penaltyFactor,
        patternId,
        JSON.stringify(triggeringFailures),
        now,
        expiresAtValue,
        null, // dismissedAt
        dismissedBy || null,
        0, // escalated
        0, // extendedCount
        null // lastExtendedAt
      );

      log.debug('Added error pattern constraint', {
        constraintId,
        agentId,
        patternId,
        expiresAt: expiresAtValue,
      });

      return constraintId;
    } catch (err) {
      log.error('Failed to add constraint', { error: err.message });
      throw err;
    }
  }

  /**
   * Get a constraint by ID.
   * @param {string} constraintId - Constraint identifier
   * @returns {Object|null} Constraint object or null if not found
   */
  get(constraintId) {
    try {
      const row = this._getStmt.get(constraintId);
      
      if (!row) {
        return null;
      }

      return this._rowToObject(row);
    } catch (err) {
      log.error('Failed to get constraint', { constraintId, error: err.message });
      throw err;
    }
  }

  /**
   * List all constraints with optional filtering.
   * @param {Object} [options] - Query options
   * @param {boolean} [options.activeOnly=true] - If true, only return active (non-dismissed, non-expired) constraints
   * @returns {Array<Object>} Array of constraint objects
   */
  list(options = {}) {
    const { activeOnly = true } = options;

    try {
      if (activeOnly) {
        const now = new Date().toISOString();
        const rows = this._listActiveStmt.all(now);
        return rows.map(row => this._rowToObject(row));
      } else {
        // Return all constraints (including dismissed/expired)
        const allStmt = this.db.prepare(`
          SELECT id, agentId, errorCategory, penaltyFactor, patternId, triggeringFailures,
                 createdAt, expiresAt, dismissedAt, dismissedBy, escalated, extendedCount, lastExtendedAt
          FROM error_pattern_constraints
          ORDER BY createdAt DESC
        `);

        const rows = allStmt.all();
        return rows.map(row => this._rowToObject(row));
      }
    } catch (err) {
      log.error('Failed to list constraints', { error: err.message });
      throw err;
    }
  }

  /**
   * Get all active (non-dismissed, non-expired) constraints.
   * Convenience method equivalent to list({ activeOnly: true }).
   * @returns {Array<Object>} Array of active constraint objects
   */
  getActiveConstraints() {
    return this.list({ activeOnly: true });
  }

  /**
   * Remove (dismiss) a constraint.
   * @param {string} constraintId - Constraint identifier
   * @param {string} [operatorId] - Optional operator ID who dismissed it
   * @returns {boolean} True if constraint was found and removed, false otherwise
   */
  remove(constraintId, operatorId = null) {
    try {
      const now = new Date().toISOString();
      const result = this._removeStmt.run(now, operatorId || null, constraintId);
      
      if (result.changes === 0) {
        log.debug('Constraint not found for removal', { constraintId });
        return false;
      }

      log.info('Removed error pattern constraint', {
        constraintId,
        dismissedBy: operatorId,
      });

      return true;
    } catch (err) {
      log.error('Failed to remove constraint', { constraintId, error: err.message });
      throw err;
    }
  }

  /**
   * Extend a constraint's TTL.
   * @param {string} constraintId - Constraint identifier
   * @param {number|string} newExpiresAt - New expiration timestamp (ms or ISO string)
   * @returns {boolean} True if constraint was found and updated, false otherwise
   */
  updateTTL(constraintId, newExpiresAt) {
    try {
      let expiresAtValue;
      if (typeof newExpiresAt === 'number') {
        expiresAtValue = new Date(newExpiresAt).toISOString();
      } else {
        expiresAtValue = newExpiresAt;
      }

      const now = new Date().toISOString();
      const result = this._updateTTLStmt.run(expiresAtValue, now, constraintId);
      
      if (result.changes === 0) {
        log.debug('Constraint not found for TTL update', { constraintId });
        return false;
      }

      log.info('Extended error pattern constraint TTL', {
        constraintId,
        newExpiresAt: expiresAtValue,
      });

      return true;
    } catch (err) {
      log.error('Failed to update TTL', { constraintId, error: err.message });
      throw err;
    }
  }

  /**
   * Escalate a constraint to hard exclude_agents type.
   * @param {string} constraintId - Constraint identifier
   * @returns {boolean} True if constraint was found and escalated, false otherwise
   */
  escalate(constraintId) {
    try {
      const result = this._escalateStmt.run(constraintId);
      
      if (result.changes === 0) {
        log.debug('Constraint not found for escalation', { constraintId });
        return false;
      }

      log.info('Escalated error pattern constraint', {
        constraintId,
      });

      return true;
    } catch (err) {
      log.error('Failed to escalate constraint', { constraintId, error: err.message });
      throw err;
    }
  }

  /**
   * Prune expired constraints and return array of expired constraint objects.
   * @param {string} [nowIso] - Optional current timestamp in ISO format (for testing)
   * @returns {Array<Object>} Array of expired constraint objects that were removed
   */
  pruneExpired(nowIso) {
    const now = nowIso || new Date().toISOString();
    const expiredConstraints = [];

    try {
      // Find all expired constraints (get full row data before deletion)
      const getExpiredStmt = this.db.prepare(`
        SELECT id, agentId, errorCategory, penaltyFactor, patternId, triggeringFailures,
               createdAt, expiresAt, dismissedAt, dismissedBy, escalated, extendedCount, lastExtendedAt
        FROM error_pattern_constraints
        WHERE dismissedAt IS NULL
          AND expiresAt IS NOT NULL
          AND expiresAt <= ?
      `);

      const rows = getExpiredStmt.all(now);

      for (const row of rows) {
        // Convert row to object before deletion
        const constraint = this._rowToObject(row);
        expiredConstraints.push(constraint);

        // Delete the expired constraint
        this._deleteExpiredStmt.run(row.id);
      }

      if (expiredConstraints.length > 0) {
        log.info('Pruned expired constraints', {
          count: expiredConstraints.length,
          constraintIds: expiredConstraints.slice(0, 10).map(c => c.id), // Log first 10 IDs
        });
      }

      return expiredConstraints;
    } catch (err) {
      log.error('Failed to prune expired constraints', { error: err.message });
      throw err;
    }
  }

  /**
   * Dismiss a constraint with operator audit trail.
   * Removes the constraint from active state and emits an ERROR_CONSTRAINT_DISMISSED
   * timeline event for the audit trail.
   *
   * @param {string} constraintId - Constraint identifier
   * @param {string} [operatorId] - Operator who dismissed the constraint
   * @param {Object} [timelineStore] - Timeline store for audit trail emission
   * @returns {boolean} True if constraint was found and dismissed, false otherwise
   */
  dismissConstraint(constraintId, operatorId = null, timelineStore = null) {
    const constraint = this.get(constraintId);
    if (!constraint) {
      log.debug('dismissConstraint: constraint not found', { constraintId });
      return false;
    }

    const removed = this.remove(constraintId, operatorId);
    if (!removed) {
      return false;
    }

    // Emit audit trail event if timeline store is provided
    if (timelineStore) {
      const event = {
        id: `constraint-dismiss-${randomUUID()}`,
        type: EVENT_TYPES.ERROR_CONSTRAINT_DISMISSED,
        timestamp: new Date().toISOString(),
        summary: `Operator dismissed error-pattern constraint for agent ${constraint.agentId}`,
        correlationKeys: {
          agentId: constraint.agentId,
        },
        data: {
          constraintId,
          agentId: constraint.agentId,
          errorCategory: constraint.errorCategory || null,
          operatorId: operatorId || 'system',
        },
      };

      const validation = validateTimelineEvent(event);
      if (!validation.valid) {
        log.error('dismissConstraint: timeline event validation failed', { errors: validation.errors });
      } else {
        try {
          timelineStore.appendRoutingEvent(event);
          log.info('Emitted ERROR_CONSTRAINT_DISMISSED audit trail event', { constraintId, operatorId });
        } catch (err) {
          log.error('dismissConstraint: failed to emit timeline event', { error: err.message });
        }
      }
    }

    return true;
  }

  /**
   * Process expired constraints: prune them and emit ERROR_CONSTRAINT_EXPIRED timeline
   * events for each one. This is the auto-expiry mechanism with audit trail support.
   *
   * @param {Object} [timelineStore] - Timeline store for expiry event emission
   * @param {string} [nowIso] - Optional current timestamp in ISO format (for testing)
   * @returns {Array<Object>} Array of expired constraint objects that were removed
   */
  processExpiredConstraints(timelineStore = null, nowIso = null) {
    const expired = this.pruneExpired(nowIso);

    if (expired.length === 0) {
      return expired;
    }

    if (!timelineStore) {
      return expired;
    }

    for (const constraint of expired) {
      const event = {
        id: `constraint-expired-${randomUUID()}`,
        type: EVENT_TYPES.ERROR_CONSTRAINT_EXPIRED,
        timestamp: new Date().toISOString(),
        summary: `Error-pattern constraint expired for agent ${constraint.agentId}`,
        correlationKeys: {
          agentId: constraint.agentId,
        },
        data: {
          constraintId: constraint.id,
          agentId: constraint.agentId,
          errorCategory: constraint.errorCategory || null,
          createdAt: constraint.createdAt,
          expiresAt: constraint.expiresAt,
        },
      };

      const validation = validateTimelineEvent(event);
      if (!validation.valid) {
        log.error('processExpiredConstraints: timeline event validation failed', {
          constraintId: constraint.id,
          errors: validation.errors,
        });
        continue;
      }

      try {
        timelineStore.appendRoutingEvent(event);
        log.info('Emitted ERROR_CONSTRAINT_EXPIRED timeline event', {
          constraintId: constraint.id,
          agentId: constraint.agentId,
          expiresAt: constraint.expiresAt,
        });
      } catch (err) {
        log.error('processExpiredConstraints: failed to emit timeline event', {
          constraintId: constraint.id,
          error: err.message,
        });
      }
    }

    return expired;
  }

  /**
   * Start a periodic watcher that auto-expires constraints and emits timeline events.
   *
   * @param {Object} timelineStore - Timeline store for expiry event emission
   * @param {number} [intervalMs=60000] - How often to check for expired constraints (default: 1 minute)
   * @returns {void}
   */
  startExpiryWatcher(timelineStore, intervalMs = 60000) {
    if (this._expiryInterval) {
      log.warn('startExpiryWatcher: watcher already running');
      return;
    }

    this._expiryInterval = setInterval(() => {
      try {
        const expired = this.processExpiredConstraints(timelineStore);
        if (expired.length > 0) {
          log.info('Expiry watcher pruned constraints', { count: expired.length });
        }
      } catch (err) {
        log.error('Expiry watcher error', { error: err.message });
      }
    }, intervalMs);

    // Allow the process to exit even if interval is still running
    if (this._expiryInterval.unref) {
      this._expiryInterval.unref();
    }

    log.info('Started constraint expiry watcher', { intervalMs });
  }

  /**
   * Stop the periodic expiry watcher.
   */
  stopExpiryWatcher() {
    if (this._expiryInterval) {
      clearInterval(this._expiryInterval);
      this._expiryInterval = null;
      log.info('Stopped constraint expiry watcher');
    }
  }

  /**
   * Close the database connection and stop any running watcher.
   */
  close() {
    this.stopExpiryWatcher();
    if (this.db) {
      this.db.close();
      this.db = null;
    }
  }

  /**
   * Convert a database row to a constraint object.
   * @param {Object} row - Database row
   * @returns {Object} Constraint object
   * @private
   */
  _rowToObject(row) {
    let triggeringFailures = [];
    try {
      if (row.triggeringFailures) {
        triggeringFailures = JSON.parse(row.triggeringFailures);
      }
    } catch (err) {
      log.warn('Failed to parse triggeringFailures JSON', {
        constraintId: row.id,
        error: err.message,
      });
      triggeringFailures = [];
    }

    return {
      id: row.id,
      agentId: row.agentId,
      errorCategory: row.errorCategory,
      penaltyFactor: row.penaltyFactor,
      patternId: row.patternId,
      triggeringFailures,
      createdAt: row.createdAt,
      expiresAt: row.expiresAt,
      dismissedAt: row.dismissedAt,
      dismissedBy: row.dismissedBy,
      escalated: row.escalated === 1,
      extendedCount: row.extendedCount,
      lastExtendedAt: row.lastExtendedAt,
    };
  }
}

/**
 * Create an ErrorPatternConstraintStore instance.
 * @param {Object} options - Store configuration
 * @param {string} options.dbPath - Path to SQLite database file
 * @param {number} [options.defaultTtlMs] - Default TTL in ms
 * @returns {ErrorPatternConstraintStore} Store instance
 */
export function createErrorPatternConstraintStore(options = {}) {
  const store = new ErrorPatternConstraintStore(options);
  return {
    add: store.add.bind(store),
    get: store.get.bind(store),
    list: store.list.bind(store),
    getActiveConstraints: store.getActiveConstraints.bind(store),
    remove: store.remove.bind(store),
    dismissConstraint: store.dismissConstraint.bind(store),
    updateTTL: store.updateTTL.bind(store),
    escalate: store.escalate.bind(store),
    pruneExpired: store.pruneExpired.bind(store),
    processExpiredConstraints: store.processExpiredConstraints.bind(store),
    startExpiryWatcher: store.startExpiryWatcher.bind(store),
    stopExpiryWatcher: store.stopExpiryWatcher.bind(store),
    close: store.close.bind(store),
  };
}

export default ErrorPatternConstraintStore;
